contract InvMutTest {
    using SafeTransferLib for address payable;
    using SafeTransferLib for address;
    using SafeTransferLib for ERC20;
    using LibClone for address;

    C c;

    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bool payRoyalties,
        uint256[] memory sellerTokenIds,
        uint256 baseTokenAmount
    ) public payable {
        require(!c.initialized(), "ALREADY_INITIALIZED");
        require(sellerTokenIds.length == 1, "ONE_NFT_ONLY");
        require(address(this).balance >= 0, "BALANCE_OK");

        c.initialize(
            baseToken,
            address(this),
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            payRoyalties
        );

        c.deposit{value: baseTokenAmount}(new uint256[](0), baseTokenAmount);

        ERC721(address(this)).transferFrom(address(this), address(c), sellerTokenIds[0]);

        uint256 cBalanceBefore = baseToken == address(0) ? address(c).balance : ERC20(baseToken).balanceOf(address(c));
        uint256 thisBalanceBefore = address(this).balance;

        uint256 minted = sellerTokenIds[0];
        uint256[] memory ids = new uint256[](1);
        ids[0] = minted;
        uint256[] memory weights = new uint256[](1);
        weights[0] = 1e18;
        C.MerkleMultiProof memory proof = C.MerkleMultiProof(new bytes32[](0), new bool[](0));
        IStolenNftOracle.Message[] memory stolenProofs = new IStolenNftOracle.Message[](0);

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.sell(ids, weights, proof, stolenProofs);

        uint256 totalOut = netOutputAmount + feeAmount + protocolFeeAmount;
        uint256 cBalanceAfter = baseToken == address(0) ? address(c).balance : ERC20(baseToken).balanceOf(address(c));
        uint256 thisBalanceAfter = address(this).balance;

        assert(totalOut <= cBalanceBefore && cBalanceAfter + totalOut == cBalanceBefore);
    }

    receive() external payable {}
}

