contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 tokenId, uint256 baseTokenAmount) public payable {
        address poolNftOwner = c.ownerOf(uint256(uint160(address(c))));
        bool isFactoryOwner = poolNftOwner == address(this) && poolNftOwner != address(0);

        require(address(this).balance >= baseTokenAmount);

        bool reverted;
        try c.deposit{value: msg.value}(new uint256[](0), baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted || !isFactoryOwner);
    }
}

